mapper.select:
SELECT w.user_id AS userId, u.user_name AS userName, u.nickname AS nickname, u.phone AS phone, u.grade_short AS gradeShort, COUNT(1) AS wrongTotal, SUM(CASE WHEN w.mastered = 0 THEN 1 ELSE 0 END) AS pendingCount, SUM(CASE WHEN w.mastered = 1 THEN 1 ELSE 0 END) AS masteredCount, GROUP_CONCAT(DISTINCT w.subject ORDER BY w.subject SEPARATOR '、') AS subjects, MAX(w.last_practice_at) AS lastPracticeAt FROM tb_user_question_wrong w LEFT JOIN tb_user u ON u.user_id = w.user_id
AND w.user_id = #{params.userId}
AND u.phone LIKE CONCAT('%', #{params.phone}, '%')
AND u.user_name LIKE CONCAT('%', #{params.userName}, '%')
AND w.subject = #{params.subject}
AND w.mastered = #{params.masteredFlag}
GROUP BY w.user_id, u.user_name, u.nickname, u.phone, u.grade_short ORDER BY lastPracticeAt DESC, w.user_id DESC
